<?php

declare(strict_types=1);

namespace Database\Factories;

use App\Enums\Gender;
use App\Models\Patient;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Patient>
 */
class PatientFactory extends Factory
{
    public function definition(): array
    {
        return [
            'patient_code' => '', // Auto-generated by the model
            'name' => fake()->name(),
            'phone' => '+1-555-'.fake()->unique()->numerify('####'),
            'email' => fake()->optional(0.6)->safeEmail(),
            'date_of_birth' => fake()->optional(0.7)->dateTimeBetween('-80 years', '-5 years')?->format('Y-m-d'),
            'gender' => fake()->optional(0.7)->randomElement(Gender::cases())->value,
            'address_line_1' => fake()->optional(0.5)->streetAddress(),
            'address_line_2' => null,
            'city' => fake()->optional(0.5)->city(),
            'state' => fake()->optional(0.5)->state(),
            'postal_code' => fake()->optional(0.5)->postcode(),
            'country' => 'Bangladesh',
            'emergency_contact_name' => fake()->optional(0.3)->name(),
            'emergency_contact_phone' => fake()->optional(0.3)->numerify('+1-555-####'),
            'medical_history' => fake()->optional(0.3)->sentence(),
            'dental_history' => null,
            'notes' => null,
            'is_active' => true,
        ];
    }

    public function inactive(): static
    {
        return $this->state(fn (): array => ['is_active' => false]);
    }

    public function withPhone(string $phone): static
    {
        return $this->state(fn (): array => ['phone' => $phone]);
    }

    public function withMedicalHistory(): static
    {
        return $this->state(fn (): array => [
            'medical_history' => 'Penicillin allergy. Hypertension controlled with medication.',
            'dental_history' => 'Two prior fillings (2018, 2022). No surgeries.',
        ]);
    }
}
